package com.spring.digital_logistics;

import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Testcontainers;

@SpringBootTest
@Testcontainers
public abstract class IntegrationTestBase {

    // Voici la solution :
    // 1. On donne un alias réseau au conteneur pour que les autres puissent l'appeler par ce nom.
    // 2. On le connecte au même réseau que Jenkins.
    static PostgreSQLContainer<?> database = new PostgreSQLContainer<>("postgres:15-alpine")
            .withNetworkAliases("postgres-for-test") // Un nom simple pour la base de données
            .withNetworkMode("jenkins-net"); // Le réseau de Jenkins !

    @DynamicPropertySource
    static void configureProperties(DynamicPropertyRegistry registry) {
        database.start();

        // On utilise l'URL interne au réseau Docker. C'est plus robuste.
        String jdbcUrl = String.format("jdbc:postgresql://postgres-for-test:%d/%s",
            5432, // Le port STANDARD de postgres, car ils sont sur le même réseau
            database.getDatabaseName());

        registry.add("spring.datasource.url", () -> jdbcUrl);
        registry.add("spring.datasource.username", database::getUsername);
        registry.add("spring.datasource.password", database::getPassword);

        registry.add("spring.jpa.hibernate.ddl-auto", () -> "update"); // 'update' est plus sûr que 'create-drop'
        registry.add("spring.jpa.database-platform", () -> "org.hibernate.dialect.PostgreSQLDialect");
        registry.add("jwt.secret", () -> "secret-key-for-integration-tests");
        registry.add("spring.docker.compose.enabled", () -> "false");
    }
}
